INSERT INTO `complaints` VALUES (1,'2026-09-25','PT Djarum','Dilakukan switching pasokan lebih awal ke TS JES akibat keterlambatan pasokan backup CNG dari RCE, dan pemanfaatan bahan bakar solar.','TS RCE sudah diterima pada pukul 21:30 WIB. Surat informasi mitigasi telah dikirim ke pelanggan.','Kualitas Suplai Gas CNG','Normal','Monitoring',NULL,'Pasokan normal kembali. Customer sudah menerima informasi mitigasi.','2026-10-19T11:41:28'),(2,'2026-09-25','PT Surya Pamenang Global','Operasional sempat terhenti akibat keterlambatan pasokan backup CNG, unit backup, seluruh alokasi konsumsi gas dialihkan secara penuh ke PRS JES.','TS RCE sudah diterima pada pukul 21:30 WIB. Surat informasi mitigasi telah dikirim ke pelanggan.','Keterlambatan Pengiriman','Tinggi','Closed','2026-10-15T18:04:34','Pasokan normal kembali. Customer sudah menerima informasi mitigasi.','2026-10-19T11:40:47');
